INSERT INTO public.maternal_content (week_start,week_end,weekday,slot,title,body,cta_type,cta_label,sort_order,active) VALUES (1,4,NULL,'tip','Early days — rest and confirmation','You may only have a positive test or very early symptoms. Focus on rest, hydration, and booking your first antenatal contact when you can. This is general guidance, not a diagnosis. If you feel unsafe or unsure, use Solace SOS or seek care now.','none',NULL,1,true);
INSERT INTO public.maternal_content (week_start,week_end,weekday,slot,title,body,cta_type,cta_label,sort_order,active) VALUES (1,4,2,'nutrition','Folic acid matters early','If your clinician advised folic acid, take it as prescribed. Leafy greens and fortified foods support early development. Avoid alcohol. This is general guidance, not a diagnosis. If you feel unsafe or unsure, use Solace SOS or seek care now.','none',NULL,2,true);
INSERT INTO public.maternal_content (week_start,week_end,weekday,slot,title,body,cta_type,cta_label,sort_order,active) VALUES (1,4,4,'safety','Heavy bleeding or severe pain','Soaking pads quickly, passing clots, or severe one-sided pain needs urgent care — these can signal miscarriage or ectopic pregnancy. This is general guidance, not a diagnosis. If you feel unsafe or unsure, use Solace SOS or seek care now.','sos','SOS if bleeding or severe pain',3,true);
INSERT INTO public.maternal_content (week_start,week_end,weekday,slot,title,body,cta_type,cta_label,sort_order,active) VALUES (1,4,5,'prepare','Save your callback number','In Profile, confirm the phone dispatchers and drivers should call. Keep Medical ID (blood group if known) up to date.','profile','Open Medical ID',4,true);
INSERT INTO public.maternal_content (week_start,week_end,weekday,slot,title,body,cta_type,cta_label,sort_order,active) VALUES (1,4,6,'mind','It is okay to feel uncertain','Early pregnancy brings hope and anxiety. Share concerns with a trusted person. Solace is here if a medical emergency arises.','none',NULL,5,true);
INSERT INTO public.maternal_content (week_start,week_end,weekday,slot,title,body,cta_type,cta_label,sort_order,active) VALUES (5,8,NULL,'tip','Nausea and fatigue are common','Small frequent meals, ginger tea if tolerated, and short rests can help. Persistent vomiting that stops you keeping fluids down needs clinical review. This is general guidance, not a diagnosis. If you feel unsafe or unsure, use Solace SOS or seek care now.','none',NULL,1,true);
INSERT INTO public.maternal_content (week_start,week_end,weekday,slot,title,body,cta_type,cta_label,sort_order,active) VALUES (5,8,2,'nutrition','Protein and steady energy','Try eggs, beans, yoghurt, or soft meats if you can keep them down. Sip water through the day even if food is hard.','none',NULL,2,true);
INSERT INTO public.maternal_content (week_start,week_end,weekday,slot,title,body,cta_type,cta_label,sort_order,active) VALUES (5,8,3,'comfort','Smell and taste changes','Strong smells may trigger nausea. Bland foods (rice, plantain, bread) often sit better.','none',NULL,3,true);
INSERT INTO public.maternal_content (week_start,week_end,weekday,slot,title,body,cta_type,cta_label,sort_order,active) VALUES (5,8,4,'safety','One-sided pain or shoulder tip pain','Severe pain on one side of the abdomen, dizziness, or fainting can be an emergency. Do not wait it out alone. This is general guidance, not a diagnosis. If you feel unsafe or unsure, use Solace SOS or seek care now.','sos','SOS now',4,true);
INSERT INTO public.maternal_content (week_start,week_end,weekday,slot,title,body,cta_type,cta_label,sort_order,active) VALUES (5,8,5,'prepare','Antenatal booking','Plan your first clinic visit. Note allergies and medications in Medical ID for responders.','profile','Update Medical ID',5,true);
INSERT INTO public.maternal_content (week_start,week_end,weekday,slot,title,body,cta_type,cta_label,sort_order,active) VALUES (5,8,6,'mind','Tell one support person','Choose who you will call day or night. Add their number in your emergency profile when possible.','none',NULL,6,true);
INSERT INTO public.maternal_content (week_start,week_end,weekday,slot,title,body,cta_type,cta_label,sort_order,active) VALUES (9,12,NULL,'tip','End of the first trimester approaches','Energy may slowly return for some people. Continue prenatal vitamins as advised. Report any bleeding to your clinician. This is general guidance, not a diagnosis. If you feel unsafe or unsure, use Solace SOS or seek care now.','none',NULL,1,true);
INSERT INTO public.maternal_content (week_start,week_end,weekday,slot,title,body,cta_type,cta_label,sort_order,active) VALUES (9,12,2,'nutrition','Iron-rich meals','Beans, lean meat, leafy vegetables, and fortified cereals help. Pair plant iron with citrus or tomatoes when you can.','none',NULL,2,true);
INSERT INTO public.maternal_content (week_start,week_end,weekday,slot,title,body,cta_type,cta_label,sort_order,active) VALUES (9,12,3,'comfort','Constipation and bloating','Water, walking, and fibre (fruit, vegetables, oats) help. Ask your clinician before any laxative.','none',NULL,3,true);
INSERT INTO public.maternal_content (week_start,week_end,weekday,slot,title,body,cta_type,cta_label,sort_order,active) VALUES (9,12,4,'safety','Bleeding with pain or dizziness','Any bright red bleeding with cramps, weakness, or fainting is an emergency — use Solace SOS or go to care immediately. This is general guidance, not a diagnosis. If you feel unsafe or unsure, use Solace SOS or seek care now.','sos','SOS for bleeding',4,true);
INSERT INTO public.maternal_content (week_start,week_end,weekday,slot,title,body,cta_type,cta_label,sort_order,active) VALUES (9,12,5,'prepare','Know your nearest capable facility','Ask your clinician which hospital is appropriate for obstetric emergencies near you.','none',NULL,5,true);
INSERT INTO public.maternal_content (week_start,week_end,weekday,slot,title,body,cta_type,cta_label,sort_order,active) VALUES (9,12,6,'mind','Mood swings are common','Hormones and fatigue affect mood. Persistent hopelessness deserves professional support.','none',NULL,6,true);
INSERT INTO public.maternal_content (week_start,week_end,weekday,slot,title,body,cta_type,cta_label,sort_order,active) VALUES (13,16,NULL,'tip','Second trimester — often a steadier phase','Many people feel more energy. Keep antenatal appointments and ask about vaccines your clinic recommends. This is general guidance, not a diagnosis. If you feel unsafe or unsure, use Solace SOS or seek care now.','none',NULL,1,true);
INSERT INTO public.maternal_content (week_start,week_end,weekday,slot,title,body,cta_type,cta_label,sort_order,active) VALUES (13,16,2,'nutrition','Calcium patterns','Dairy, fortified alternatives, and local clinical advice on supplements support bone health.','none',NULL,2,true);
INSERT INTO public.maternal_content (week_start,week_end,weekday,slot,title,body,cta_type,cta_label,sort_order,active) VALUES (13,16,3,'comfort','Round ligament twinges','Sharp side pulls when standing quickly are common. Severe or constant pain still needs checking. This is general guidance, not a diagnosis. If you feel unsafe or unsure, use Solace SOS or seek care now.','none',NULL,3,true);
INSERT INTO public.maternal_content (week_start,week_end,weekday,slot,title,body,cta_type,cta_label,sort_order,active) VALUES (13,16,4,'safety','Fever, chills, or burning urine','High fever or inability to keep fluids needs timely care in pregnancy. This is general guidance, not a diagnosis. If you feel unsafe or unsure, use Solace SOS or seek care now.','sos','SOS if very unwell',4,true);
INSERT INTO public.maternal_content (week_start,week_end,weekday,slot,title,body,cta_type,cta_label,sort_order,active) VALUES (13,16,5,'prepare','Document blood group if known','If you know your blood group, save it under Medical ID.','profile','Edit Medical ID',5,true);
INSERT INTO public.maternal_content (week_start,week_end,weekday,slot,title,body,cta_type,cta_label,sort_order,active) VALUES (13,16,6,'mind','Share the plan with family','Explain that Solace can request an ambulance if something feels wrong.','none',NULL,6,true);
INSERT INTO public.maternal_content (week_start,week_end,weekday,slot,title,body,cta_type,cta_label,sort_order,active) VALUES (17,20,NULL,'tip','Movement and checks','You may feel flutters. Attend scheduled checks your clinic offers. This is general guidance, not a diagnosis. If you feel unsafe or unsure, use Solace SOS or seek care now.','none',NULL,1,true);
INSERT INTO public.maternal_content (week_start,week_end,weekday,slot,title,body,cta_type,cta_label,sort_order,active) VALUES (17,20,2,'nutrition','Balanced plates','Protein, vegetable or fruit, and a staple most meals. Limit sugary drinks.','none',NULL,2,true);
INSERT INTO public.maternal_content (week_start,week_end,weekday,slot,title,body,cta_type,cta_label,sort_order,active) VALUES (17,20,3,'comfort','Back support','Soft shoes and a pillow behind your back when sitting reduce strain.','none',NULL,3,true);
INSERT INTO public.maternal_content (week_start,week_end,weekday,slot,title,body,cta_type,cta_label,sort_order,active) VALUES (17,20,4,'safety','Severe headache or vision changes','Sudden severe headache, vision spots, or sudden facial swelling need urgent care. This is general guidance, not a diagnosis. If you feel unsafe or unsure, use Solace SOS or seek care now.','sos','SOS for headache/vision',4,true);
INSERT INTO public.maternal_content (week_start,week_end,weekday,slot,title,body,cta_type,cta_label,sort_order,active) VALUES (17,20,5,'prepare','Birth preference notes','Note preferred hospital and allergies in Profile.','none',NULL,5,true);
INSERT INTO public.maternal_content (week_start,week_end,weekday,slot,title,body,cta_type,cta_label,sort_order,active) VALUES (17,20,0,'review','Mid-pregnancy check-in','Confirm visit dates, medication list, and callback number.','profile','Review profile',6,true);
INSERT INTO public.maternal_content (week_start,week_end,weekday,slot,title,body,cta_type,cta_label,sort_order,active) VALUES (21,24,NULL,'tip','Growing belly — posture and rest','Short walks and side-lying rest often help. Report rhythmic painful tightenings before 37 weeks. This is general guidance, not a diagnosis. If you feel unsafe or unsure, use Solace SOS or seek care now.','none',NULL,1,true);
INSERT INTO public.maternal_content (week_start,week_end,weekday,slot,title,body,cta_type,cta_label,sort_order,active) VALUES (21,24,2,'nutrition','Hydration target','Regular water intake (about 2–3 litres unless restricted). Dehydration can worsen tightenings.','none',NULL,2,true);
INSERT INTO public.maternal_content (week_start,week_end,weekday,slot,title,body,cta_type,cta_label,sort_order,active) VALUES (21,24,3,'comfort','Leg cramps at night','Gentle calf stretches and fluids help some. Sudden one-sided leg swelling with pain needs urgent review. This is general guidance, not a diagnosis. If you feel unsafe or unsure, use Solace SOS or seek care now.','none',NULL,3,true);
INSERT INTO public.maternal_content (week_start,week_end,weekday,slot,title,body,cta_type,cta_label,sort_order,active) VALUES (21,24,4,'safety','Fluid leak or gush','Continuous watery leak may be ruptured membranes. Note time and colour; seek care. This is general guidance, not a diagnosis. If you feel unsafe or unsure, use Solace SOS or seek care now.','sos','SOS if water broke',4,true);
INSERT INTO public.maternal_content (week_start,week_end,weekday,slot,title,body,cta_type,cta_label,sort_order,active) VALUES (21,24,5,'prepare','Hospital bag draft list','ID, clinic card, pads, clean clothes, phone charger, transport plan for support person.','none',NULL,5,true);
INSERT INTO public.maternal_content (week_start,week_end,weekday,slot,title,body,cta_type,cta_label,sort_order,active) VALUES (21,24,6,'mind','Sleep disruption','Side-lying with a pillow between knees helps many.','none',NULL,6,true);
INSERT INTO public.maternal_content (week_start,week_end,weekday,slot,title,body,cta_type,cta_label,sort_order,active) VALUES (25,27,NULL,'tip','Third trimester approaching','Baby movements become a daily language. Learn what is normal for you. This is general guidance, not a diagnosis. If you feel unsafe or unsure, use Solace SOS or seek care now.','none',NULL,1,true);
INSERT INTO public.maternal_content (week_start,week_end,weekday,slot,title,body,cta_type,cta_label,sort_order,active) VALUES (25,27,2,'nutrition','Iron and vitamin C','If prescribed iron, take as directed — often with vitamin C rich food.','none',NULL,2,true);
INSERT INTO public.maternal_content (week_start,week_end,weekday,slot,title,body,cta_type,cta_label,sort_order,active) VALUES (25,27,3,'comfort','Heartburn','Smaller meals; avoid lying flat right after eating. Ask before antacids.','none',NULL,3,true);
INSERT INTO public.maternal_content (week_start,week_end,weekday,slot,title,body,cta_type,cta_label,sort_order,active) VALUES (25,27,4,'safety','Reduced movements','If movements are clearly less than usual, contact maternity care or use Solace SOS. This is general guidance, not a diagnosis. If you feel unsafe or unsure, use Solace SOS or seek care now.','sos','SOS if movements reduced',4,true);
INSERT INTO public.maternal_content (week_start,week_end,weekday,slot,title,body,cta_type,cta_label,sort_order,active) VALUES (25,27,5,'prepare','Who comes with you','Agree which person meets you at hospital and handles other logistics.','none',NULL,5,true);
INSERT INTO public.maternal_content (week_start,week_end,weekday,slot,title,body,cta_type,cta_label,sort_order,active) VALUES (25,27,6,'mind','Anxiety about birth','Write questions for your next clinic visit. Emergency planning with Solace is one practical step.','none',NULL,6,true);
INSERT INTO public.maternal_content (week_start,week_end,weekday,slot,title,body,cta_type,cta_label,sort_order,active) VALUES (28,28,NULL,'tip','Week 28 — stay tuned to movements','At week 28, keep a simple sense of your baby daily pattern. Report a clear drop the same day. This is general guidance, not a diagnosis. If you feel unsafe or unsure, use Solace SOS or seek care now.','none',NULL,1,true);
INSERT INTO public.maternal_content (week_start,week_end,weekday,slot,title,body,cta_type,cta_label,sort_order,active) VALUES (28,28,2,'nutrition','Steady meals, less long fasting','Long gaps without food can make you dizzy. Carry a small snack when you leave home.','none',NULL,2,true);
INSERT INTO public.maternal_content (week_start,week_end,weekday,slot,title,body,cta_type,cta_label,sort_order,active) VALUES (28,28,3,'comfort','Swelling watch','Mild ankle swelling after standing is common. Sudden face or hand swelling with headache is not. This is general guidance, not a diagnosis. If you feel unsafe or unsure, use Solace SOS or seek care now.','none',NULL,3,true);
INSERT INTO public.maternal_content (week_start,week_end,weekday,slot,title,body,cta_type,cta_label,sort_order,active) VALUES (28,28,4,'safety','Pre-eclampsia warning pattern','Severe headache, vision sparks, upper abdominal pain, or sudden swelling need urgent review or SOS. This is general guidance, not a diagnosis. If you feel unsafe or unsure, use Solace SOS or seek care now.','sos','SOS for danger signs',4,true);
INSERT INTO public.maternal_content (week_start,week_end,weekday,slot,title,body,cta_type,cta_label,sort_order,active) VALUES (28,28,5,'prepare','Confirm Solace Medical ID','Verify name, phone, blood group, and Maternal care plan in Profile.','profile','Open Profile',5,true);
INSERT INTO public.maternal_content (week_start,week_end,weekday,slot,title,body,cta_type,cta_label,sort_order,active) VALUES (28,28,6,'mind','Rest without guilt','Naps and saying no to extra tasks protect you and the baby.','none',NULL,6,true);
INSERT INTO public.maternal_content (week_start,week_end,weekday,slot,title,body,cta_type,cta_label,sort_order,active) VALUES (28,28,0,'review','Kick awareness (guidance only)','Know your baby pattern; act the same day if it changes markedly. This is general guidance, not a diagnosis. If you feel unsafe or unsure, use Solace SOS or seek care now.','none',NULL,7,true);
INSERT INTO public.maternal_content (week_start,week_end,weekday,slot,title,body,cta_type,cta_label,sort_order,active) VALUES (29,29,NULL,'tip','Week 29 — stay tuned to movements','At week 29, keep a simple sense of your baby daily pattern. Report a clear drop the same day. This is general guidance, not a diagnosis. If you feel unsafe or unsure, use Solace SOS or seek care now.','none',NULL,1,true);
