INSERT INTO public.maternal_content (week_start,week_end,weekday,slot,title,body,cta_type,cta_label,sort_order,active) VALUES (32,32,NULL,'tip','Week 32 — birth preparation mode','Week 32: keep phone charged and bag ready. Painful regular contractions need assessment. This is general guidance, not a diagnosis. If you feel unsafe or unsure, use Solace SOS or seek care now.','none',NULL,1,true);
INSERT INTO public.maternal_content (week_start,week_end,weekday,slot,title,body,cta_type,cta_label,sort_order,active) VALUES (32,32,2,'nutrition','Small frequent meals','Smaller portions may reduce heartburn.','none',NULL,2,true);
INSERT INTO public.maternal_content (week_start,week_end,weekday,slot,title,body,cta_type,cta_label,sort_order,active) VALUES (32,32,3,'comfort','Side sleeping','Left-side lying is often encouraged. Use pillows for belly and knees. This is general guidance, not a diagnosis. If you feel unsafe or unsure, use Solace SOS or seek care now.','none',NULL,3,true);
INSERT INTO public.maternal_content (week_start,week_end,weekday,slot,title,body,cta_type,cta_label,sort_order,active) VALUES (32,32,4,'safety','Vaginal bleeding after 28 weeks','Any fresh bleeding in late pregnancy is an emergency until proven otherwise. This is general guidance, not a diagnosis. If you feel unsafe or unsure, use Solace SOS or seek care now.','sos','SOS for bleeding',4,true);
INSERT INTO public.maternal_content (week_start,week_end,weekday,slot,title,body,cta_type,cta_label,sort_order,active) VALUES (32,32,1,'safety','Water broke (PROM)','A gush or steady trickle of fluid: note time and colour. Seek maternity care. This is general guidance, not a diagnosis. If you feel unsafe or unsure, use Solace SOS or seek care now.','sos','SOS if fluid leak',5,true);
INSERT INTO public.maternal_content (week_start,week_end,weekday,slot,title,body,cta_type,cta_label,sort_order,active) VALUES (32,32,5,'prepare','Hospital bag essentials','Clinic notes, ID, pads, outfits, charger, snacks for support person.','none',NULL,6,true);
INSERT INTO public.maternal_content (week_start,week_end,weekday,slot,title,body,cta_type,cta_label,sort_order,active) VALUES (32,32,6,'mind','Birth partner brief','Show your partner the Solace SOS button and Profile details.','none',NULL,7,true);
INSERT INTO public.maternal_content (week_start,week_end,weekday,slot,title,body,cta_type,cta_label,sort_order,active) VALUES (33,33,NULL,'tip','Week 33 — birth preparation mode','Week 33: keep phone charged and bag ready. Painful regular contractions need assessment. This is general guidance, not a diagnosis. If you feel unsafe or unsure, use Solace SOS or seek care now.','none',NULL,1,true);
INSERT INTO public.maternal_content (week_start,week_end,weekday,slot,title,body,cta_type,cta_label,sort_order,active) VALUES (33,33,2,'nutrition','Small frequent meals','Smaller portions may reduce heartburn.','none',NULL,2,true);
INSERT INTO public.maternal_content (week_start,week_end,weekday,slot,title,body,cta_type,cta_label,sort_order,active) VALUES (33,33,3,'comfort','Side sleeping','Left-side lying is often encouraged. Use pillows for belly and knees. This is general guidance, not a diagnosis. If you feel unsafe or unsure, use Solace SOS or seek care now.','none',NULL,3,true);
INSERT INTO public.maternal_content (week_start,week_end,weekday,slot,title,body,cta_type,cta_label,sort_order,active) VALUES (33,33,4,'safety','Vaginal bleeding after 28 weeks','Any fresh bleeding in late pregnancy is an emergency until proven otherwise. This is general guidance, not a diagnosis. If you feel unsafe or unsure, use Solace SOS or seek care now.','sos','SOS for bleeding',4,true);
INSERT INTO public.maternal_content (week_start,week_end,weekday,slot,title,body,cta_type,cta_label,sort_order,active) VALUES (33,33,1,'safety','Water broke (PROM)','A gush or steady trickle of fluid: note time and colour. Seek maternity care. This is general guidance, not a diagnosis. If you feel unsafe or unsure, use Solace SOS or seek care now.','sos','SOS if fluid leak',5,true);
