INSERT INTO public.maternal_content (week_start,week_end,weekday,slot,title,body,cta_type,cta_label,sort_order,active) VALUES (37,37,NULL,'tip','Week 37 — term pregnancy','At week 37 keep bag ready and day/night transport plans. This is general guidance, not a diagnosis. If you feel unsafe or unsure, use Solace SOS or seek care now.','none',NULL,1,true);
INSERT INTO public.maternal_content (week_start,week_end,weekday,slot,title,body,cta_type,cta_label,sort_order,active) VALUES (37,37,2,'nutrition','Easy-to-digest energy','Light meals you tolerate. Stay hydrated unless told otherwise.','none',NULL,2,true);
INSERT INTO public.maternal_content (week_start,week_end,weekday,slot,title,body,cta_type,cta_label,sort_order,active) VALUES (37,37,3,'comfort','Pelvic pressure','Heaviness is common. Cannot pass urine, or pain with fever, needs review. This is general guidance, not a diagnosis. If you feel unsafe or unsure, use Solace SOS or seek care now.','none',NULL,3,true);
INSERT INTO public.maternal_content (week_start,week_end,weekday,slot,title,body,cta_type,cta_label,sort_order,active) VALUES (37,37,5,'prepare','Final checklist','Medical ID, callback number, hospital preference, support person, app login tested.','profile','Check Profile',5,true);
INSERT INTO public.maternal_content (week_start,week_end,weekday,slot,title,body,cta_type,cta_label,sort_order,active) VALUES (37,37,6,'mind','You can ask for help early','If something feels wrong, early contact is better than delay. This is general guidance, not a diagnosis. If you feel unsafe or unsure, use Solace SOS or seek care now.','none',NULL,6,true);
INSERT INTO public.maternal_content (week_start,week_end,weekday,slot,title,body,cta_type,cta_label,sort_order,active) VALUES (37,37,0,'review','Labour signs vs emergency','Waters breaking, fresh bleeding, severe headache, or movements stopping — use SOS when needed. This is general guidance, not a diagnosis. If you feel unsafe or unsure, use Solace SOS or seek care now.','sos','Open SOS if needed',7,true);
