INSERT INTO public.maternal_content (week_start,week_end,weekday,slot,title,body,cta_type,cta_label,sort_order,active) VALUES (41,42,NULL,'tip','Past your due date','Many births occur after the estimated date. Report reduced movements immediately. This is general guidance, not a diagnosis. If you feel unsafe or unsure, use Solace SOS or seek care now.','none',NULL,1,true);
INSERT INTO public.maternal_content (week_start,week_end,weekday,slot,title,body,cta_type,cta_label,sort_order,active) VALUES (41,42,4,'safety','Do not ignore movement changes','At post-term, same-day assessment for reduced movements is critical. This is general guidance, not a diagnosis. If you feel unsafe or unsure, use Solace SOS or seek care now.','sos','SOS now',2,true);
INSERT INTO public.maternal_content (week_start,week_end,weekday,slot,title,body,cta_type,cta_label,sort_order,active) VALUES (41,42,5,'prepare','Know induction discussion points','Your clinic may discuss induction. Keep Solace ready for unplanned labour at home. This is general guidance, not a diagnosis. If you feel unsafe or unsure, use Solace SOS or seek care now.','none',NULL,3,true);
INSERT INTO public.maternal_content (week_start,week_end,weekday,slot,title,body,cta_type,cta_label,sort_order,active) VALUES (41,42,6,'mind','Patience and vigilance together','Rest when you can, but stay alert to danger signs. This is general guidance, not a diagnosis. If you feel unsafe or unsure, use Solace SOS or seek care now.','none',NULL,4,true);
INSERT INTO public.maternal_content (week_start,week_end,weekday,slot,title,body,cta_type,cta_label,sort_order,active) VALUES (28,42,NULL,'safety','Severe persistent headache & vision','Severe headache with blurred vision or spots needs urgent obstetric assessment. This is general guidance, not a diagnosis. If you feel unsafe or unsure, use Solace SOS or seek care now.','sos','SOS now',10,true);
INSERT INTO public.maternal_content (week_start,week_end,weekday,slot,title,body,cta_type,cta_label,sort_order,active) VALUES (28,42,NULL,'safety','Marked reduction in fetal movements','Fewer movements than your normal pattern — same-day review or SOS. This is general guidance, not a diagnosis. If you feel unsafe or unsure, use Solace SOS or seek care now.','sos','SOS for reduced movements',11,true);
INSERT INTO public.maternal_content (week_start,week_end,weekday,slot,title,body,cta_type,cta_label,sort_order,active) VALUES (34,42,NULL,'safety','Regular painful contractions','Painful tightenings that grow longer and closer — especially with fluid leak or bleeding — warrant urgent care. This is general guidance, not a diagnosis. If you feel unsafe or unsure, use Solace SOS or seek care now.','sos','SOS for labour concern',12,true);
INSERT INTO public.maternal_content (week_start,week_end,weekday,slot,title,body,cta_type,cta_label,sort_order,active) VALUES (40,42,NULL,'tip','After birth — first days (read when relevant)','Heavy soaking of pads hourly, large clots, fever, severe headache, or difficulty breathing need urgent care. This is general guidance, not a diagnosis. If you feel unsafe or unsure, use Solace SOS or seek care now.','sos','SOS if post-birth emergency',20,true);
INSERT INTO public.maternal_content (week_start,week_end,weekday,slot,title,body,cta_type,cta_label,sort_order,active) VALUES (40,42,NULL,'safety','Post-birth bleeding emergency','Soaking more than one pad per hour for more than two hours, or feeling faint with bleeding, is an emergency. This is general guidance, not a diagnosis. If you feel unsafe or unsure, use Solace SOS or seek care now.','sos','SOS for heavy bleeding',21,true);
INSERT INTO public.maternal_content (week_start,week_end,weekday,slot,title,body,cta_type,cta_label,sort_order,active) VALUES (1,42,1,'prepare','Keep GPS and phone ready','Allow location permission and keep a charged power bank if outages are common.','none',NULL,100,true);
INSERT INTO public.maternal_content (week_start,week_end,weekday,slot,title,body,cta_type,cta_label,sort_order,active) VALUES (1,42,NULL,'tip','Solace is for emergencies and urgent transport','Daily tips support awareness. Sudden severe symptoms belong on the SOS path. This is general guidance, not a diagnosis. If you feel unsafe or unsure, use Solace SOS or seek care now.','none',NULL,101,true);
